from __future__ import annotations

"""Adjacent-cell math for geohash strings.

Given a geohash cell, compute the eight cells touching it (N, S, E, W and the
four diagonals). This is the standard geohash adjacency algorithm: for each
direction there are lookup tables describing how the last character changes, and
a "border" set describing when the change ripples up into the parent prefix.

The tables are indexed by [direction][parity], where parity is "even" or "odd"
depending on the cell length (odd-length and even-length cells split lat/lon in
the opposite order, so their neighbor tables are mirrored).
"""

from geohash_codec import _BASE32, is_valid_cell

# Neighbor lookup tables, keyed by direction then parity ("even"/"odd").
_NEIGHBOR = {
    "n": {
        "even": "p0r21436x8zb9dcf5h7kjnmqesgutwvy",
        "odd": "bc01fg45238967deuvhjyznpkmstqrwx",
    },
    "s": {
        "even": "14365h7k9dcfesgujnmqp0r2twvyx8zb",
        "odd": "238967debc01fg45kmstqrwxuvhjyznp",
    },
    "e": {
        "even": "bc01fg45238967deuvhjyznpkmstqrwx",
        "odd": "p0r21436x8zb9dcf5h7kjnmqesgutwvy",
    },
    "w": {
        "even": "238967debc01fg45kmstqrwxuvhjyznp",
        "odd": "14365h7k9dcfesgujnmqp0r2twvyx8zb",
    },
}

# Border sets: when the last char of a cell is in this set, the neighbor lookup
# wraps and the parent prefix must also be advanced one cell in that direction.
_BORDER = {
    "n": {"even": "prxz", "odd": "bcfguvyz"},
    "s": {"even": "028b", "odd": "0145hjnp"},
    "e": {"even": "bcfguvyz", "odd": "prxz"},
    "w": {"even": "0145hjnp", "odd": "028b"},
}

# Diagonals are composed from two cardinal moves.
_DIAGONALS = {
    "ne": ("n", "e"),
    "nw": ("n", "w"),
    "se": ("s", "e"),
    "sw": ("s", "w"),
}

CARDINALS = ("n", "s", "e", "w")
ALL_DIRECTIONS = ("n", "ne", "e", "se", "s", "sw", "w", "nw")


def adjacent(cell: str, direction: str) -> str:
    """The cell directly adjacent to ``cell`` in a cardinal direction."""

    if not is_valid_cell(cell):
        raise ValueError(f"invalid geohash cell: {cell!r}")
    direction = direction.lower()
    if direction not in CARDINALS:
        raise ValueError(f"direction must be one of {CARDINALS}")

    last = cell[-1]
    parent = cell[:-1]
    parity = "even" if (len(cell) % 2 == 0) else "odd"

    if parent and last in _BORDER[direction][parity]:
        parent = adjacent(parent, direction)

    index = _NEIGHBOR[direction][parity].index(last)
    return parent + _BASE32[index]


def diagonal(cell: str, direction: str) -> str:
    first, second = _DIAGONALS[direction.lower()]
    return adjacent(adjacent(cell, first), second)


def neighbors(cell: str) -> dict[str, str]:
    """Map of direction -> neighbor cell for all eight surrounding cells."""

    result: dict[str, str] = {}
    for direction in CARDINALS:
        result[direction] = adjacent(cell, direction)
    for name in _DIAGONALS:
        result[name] = diagonal(cell, name)
    return result


def neighbor_cells(cell: str) -> list[str]:
    """The eight surrounding cells (no particular order, no duplicates)."""

    found = neighbors(cell)
    return [found[d] for d in ALL_DIRECTIONS]


def cell_block(cell: str) -> list[str]:
    """The 3x3 block: the cell itself plus its eight neighbors, deduped."""

    block = [cell]
    for neighbor in neighbor_cells(cell):
        if neighbor not in block:
            block.append(neighbor)
    return block


def are_adjacent(cell_a: str, cell_b: str) -> bool:
    return cell_b in set(neighbor_cells(cell_a))

