from __future__ import annotations

"""Geographic points and great-circle distance for the places service.

A ``GeoPoint`` is a place of interest with a stable id and a latitude /
longitude in decimal degrees. Distance between two points is the great-circle
distance using the haversine formula, in meters, on a spherical earth with mean
radius ``EARTH_RADIUS_M``. We do not need ellipsoidal accuracy here; the search
radius is small and a sphere is well within tolerance for "near me" lookups.
"""

from dataclasses import dataclass
from math import asin, cos, radians, sin, sqrt

# Mean earth radius in meters (spherical model used everywhere in this service).
EARTH_RADIUS_M = 6_371_000.0

MIN_LAT, MAX_LAT = -90.0, 90.0
MIN_LON, MAX_LON = -180.0, 180.0


@dataclass(frozen=True)
class GeoPoint:
    point_id: str
    lat: float
    lon: float

    def __post_init__(self) -> None:
        if not self.point_id.strip():
            raise ValueError("point_id is required")
        if not (MIN_LAT <= self.lat <= MAX_LAT):
            raise ValueError("lat must be in [-90, 90]")
        if not (MIN_LON <= self.lon <= MAX_LON):
            raise ValueError("lon must be in [-180, 180]")

    def as_tuple(self) -> tuple[float, float]:
        return (self.lat, self.lon)

    @classmethod
    def from_raw(cls, raw: dict) -> "GeoPoint":
        return cls(
            point_id=str(raw.get("id") or raw.get("point_id") or ""),
            lat=float(raw["lat"]),
            lon=float(raw["lon"]),
        )


def haversine_meters(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    """Great-circle distance between two lat/lon pairs, in meters."""

    phi1 = radians(lat1)
    phi2 = radians(lat2)
    d_phi = radians(lat2 - lat1)
    d_lambda = radians(lon2 - lon1)
    a = sin(d_phi / 2.0) ** 2 + cos(phi1) * cos(phi2) * sin(d_lambda / 2.0) ** 2
    # asin form is numerically stable for the small distances we deal with.
    return 2.0 * EARTH_RADIUS_M * asin(sqrt(a))


def distance_between(a: GeoPoint, b: GeoPoint) -> float:
    return haversine_meters(a.lat, a.lon, b.lat, b.lon)


def distance_to(origin_lat: float, origin_lon: float, point: GeoPoint) -> float:
    return haversine_meters(origin_lat, origin_lon, point.lat, point.lon)


def within_radius(origin_lat: float, origin_lon: float, point: GeoPoint, radius_m: float) -> bool:
    if radius_m < 0:
        raise ValueError("radius_m must be non-negative")
    return distance_to(origin_lat, origin_lon, point) <= radius_m


def parse_points(raws: list[dict]) -> list[GeoPoint]:
    return [GeoPoint.from_raw(raw) for raw in raws]


def sort_by_distance(origin_lat: float, origin_lon: float, points: list[GeoPoint]) -> list[GeoPoint]:
    """Closest first; ties broken by id so results are deterministic."""

    return sorted(
        points,
        key=lambda p: (distance_to(origin_lat, origin_lon, p), p.point_id),
    )


def nearest(origin_lat: float, origin_lon: float, points: list[GeoPoint]) -> GeoPoint | None:
    if not points:
        return None
    return sort_by_distance(origin_lat, origin_lon, points)[0]

