from __future__ import annotations

"""Geohash encoding/decoding at a fixed precision.

A geohash maps a (lat, lon) pair to a short base-32 string by repeatedly
bisecting the latitude and longitude ranges and interleaving the bits
(longitude bit first at each step). Two nearby points usually share a prefix,
which is what makes geohashes handy for bucketing places into cells.

Precision is the number of base-32 characters in the cell string; more
characters means smaller cells. The codec also exposes the decoded cell as a
center plus a half-height / half-width error box, which neighbor math relies on.
"""

# Base-32 alphabet used by the standard geohash scheme (no a, i, l, o).
_BASE32 = "0123456789bcdefghjkmnpqrstuvwxyz"
_DECODE_MAP = {ch: i for i, ch in enumerate(_BASE32)}

LAT_RANGE = (-90.0, 90.0)
LON_RANGE = (-180.0, 180.0)


def encode(lat: float, lon: float, precision: int = 7) -> str:
    """Encode a coordinate into a geohash cell of ``precision`` characters."""

    if precision < 1:
        raise ValueError("precision must be >= 1")
    if not (LAT_RANGE[0] <= lat <= LAT_RANGE[1]):
        raise ValueError("lat out of range")
    if not (LON_RANGE[0] <= lon <= LON_RANGE[1]):
        raise ValueError("lon out of range")

    lat_lo, lat_hi = LAT_RANGE
    lon_lo, lon_hi = LON_RANGE

    geohash_chars: list[str] = []
    bits = 0
    bit_count = 0
    even_bit = True  # When True we bisect longitude; standard scheme starts here.

    while len(geohash_chars) < precision:
        if even_bit:
            mid = (lon_lo + lon_hi) / 2.0
            if lon >= mid:
                bits = (bits << 1) | 1
                lon_lo = mid
            else:
                bits = bits << 1
                lon_hi = mid
        else:
            mid = (lat_lo + lat_hi) / 2.0
            if lat >= mid:
                bits = (bits << 1) | 1
                lat_lo = mid
            else:
                bits = bits << 1
                lat_hi = mid

        even_bit = not even_bit
        bit_count += 1

        if bit_count == 5:
            geohash_chars.append(_BASE32[bits])
            bits = 0
            bit_count = 0

    return "".join(geohash_chars)


def decode_bbox(cell: str) -> tuple[float, float, float, float]:
    """Return ``(lat_lo, lat_hi, lon_lo, lon_hi)`` for a geohash cell."""

    if not cell:
        raise ValueError("cell must be non-empty")

    lat_lo, lat_hi = LAT_RANGE
    lon_lo, lon_hi = LON_RANGE
    even_bit = True

    for ch in cell:
        if ch not in _DECODE_MAP:
            raise ValueError(f"invalid geohash character: {ch!r}")
        value = _DECODE_MAP[ch]
        for mask in (16, 8, 4, 2, 1):
            bit = 1 if (value & mask) else 0
            if even_bit:
                mid = (lon_lo + lon_hi) / 2.0
                if bit:
                    lon_lo = mid
                else:
                    lon_hi = mid
            else:
                mid = (lat_lo + lat_hi) / 2.0
                if bit:
                    lat_lo = mid
                else:
                    lat_hi = mid
            even_bit = not even_bit

    return (lat_lo, lat_hi, lon_lo, lon_hi)


def decode_center(cell: str) -> tuple[float, float]:
    lat_lo, lat_hi, lon_lo, lon_hi = decode_bbox(cell)
    return ((lat_lo + lat_hi) / 2.0, (lon_lo + lon_hi) / 2.0)


def cell_dimensions(cell: str) -> tuple[float, float]:
    """Cell height and width in degrees (lat span, lon span)."""

    lat_lo, lat_hi, lon_lo, lon_hi = decode_bbox(cell)
    return (lat_hi - lat_lo, lon_hi - lon_lo)


def share_prefix(cell_a: str, cell_b: str) -> int:
    """Length of the shared leading prefix of two cells."""

    shared = 0
    for ca, cb in zip(cell_a, cell_b):
        if ca != cb:
            break
        shared += 1
    return shared


def is_valid_cell(cell: str) -> bool:
    return bool(cell) and all(ch in _DECODE_MAP for ch in cell)

