from __future__ import annotations

"""Radius search over the geohash spatial index.

``nearby(lat, lon, radius_m)`` answers "every place within R meters of this
point". The flow: encode the query point to a cell, gather the candidate cells
to read from the index, then filter those candidates by true great-circle
distance and sort closest first.

Reading from the index is cheap, distance math is the expensive part, so the
candidate set is kept tight before the distance filter runs.
"""

from dataclasses import dataclass

from geo_point import GeoPoint, distance_to, sort_by_distance
from spatial_index import SpatialIndex


@dataclass(frozen=True)
class NearbyHit:
    point: GeoPoint
    distance_m: float

    @property
    def point_id(self) -> str:
        return self.point.point_id


def candidate_cells(index: SpatialIndex, lat: float, lon: float) -> list[str]:
    """Cells to scan for a query at (lat, lon)."""

    return [index.cell_for(lat, lon)]


def _filter_by_radius(
    lat: float,
    lon: float,
    points: list[GeoPoint],
    radius_m: float,
) -> list[GeoPoint]:
    return [p for p in points if distance_to(lat, lon, p) <= radius_m]


def nearby(index: SpatialIndex, lat: float, lon: float, radius_m: float) -> list[GeoPoint]:
    """Places within ``radius_m`` meters of (lat, lon), closest first."""

    if radius_m < 0:
        raise ValueError("radius_m must be non-negative")

    cells = candidate_cells(index, lat, lon)
    candidates = index.points_in_cells(cells)
    matched = _filter_by_radius(lat, lon, candidates, radius_m)
    return sort_by_distance(lat, lon, matched)


def nearby_ids(index: SpatialIndex, lat: float, lon: float, radius_m: float) -> list[str]:
    return [p.point_id for p in nearby(index, lat, lon, radius_m)]


def nearby_hits(index: SpatialIndex, lat: float, lon: float, radius_m: float) -> list[NearbyHit]:
    """Same as :func:`nearby` but each result carries its measured distance."""

    results = nearby(index, lat, lon, radius_m)
    return [NearbyHit(point=p, distance_m=distance_to(lat, lon, p)) for p in results]


