from __future__ import annotations

"""Bucket places of interest into geohash cells for fast lookup.

The index holds a fixed precision and keeps a dict of cell string -> list of
points whose coordinates encode to that cell. Inserting a point computes its
cell once and appends it to the right bucket. Lookups by cell are O(1); the
search layer decides which cells to read.
"""

from collections import defaultdict

from geo_point import GeoPoint
from geohash_codec import encode

DEFAULT_PRECISION = 7


class SpatialIndex:
    def __init__(self, precision: int = DEFAULT_PRECISION) -> None:
        if precision < 1:
            raise ValueError("precision must be >= 1")
        self.precision = precision
        self._buckets: dict[str, list[GeoPoint]] = defaultdict(list)
        self._cell_of: dict[str, str] = {}

    def cell_for(self, lat: float, lon: float) -> str:
        return encode(lat, lon, self.precision)

    def add(self, point: GeoPoint) -> str:
        cell = self.cell_for(point.lat, point.lon)
        self._buckets[cell].append(point)
        self._cell_of[point.point_id] = cell
        return cell

    def add_many(self, points: list[GeoPoint]) -> None:
        for point in points:
            self.add(point)

    def points_in_cell(self, cell: str) -> list[GeoPoint]:
        """Points stored in exactly this cell (empty list if none)."""

        return list(self._buckets.get(cell, []))

    def points_in_cells(self, cells: list[str]) -> list[GeoPoint]:
        """Points across several cells, de-duplicated by point id."""

        seen: set[str] = set()
        collected: list[GeoPoint] = []
        for cell in cells:
            for point in self._buckets.get(cell, []):
                if point.point_id in seen:
                    continue
                seen.add(point.point_id)
                collected.append(point)
        return collected

    def cell_of_point(self, point_id: str) -> str | None:
        return self._cell_of.get(point_id)

    def occupied_cells(self) -> list[str]:
        return [cell for cell, pts in self._buckets.items() if pts]

    def all_points(self) -> list[GeoPoint]:
        collected: list[GeoPoint] = []
        for pts in self._buckets.values():
            collected.extend(pts)
        return collected

    def size(self) -> int:
        return sum(len(pts) for pts in self._buckets.values())

    def bucket_sizes(self) -> dict[str, int]:
        return {cell: len(pts) for cell, pts in self._buckets.items() if pts}

    def __len__(self) -> int:
        return self.size()


def build_index(points: list[GeoPoint], precision: int = DEFAULT_PRECISION) -> SpatialIndex:
    index = SpatialIndex(precision=precision)
    index.add_many(points)
    return index

